import { describe, expect, it } from 'vitest';
import { Add, Dummy, Float, Mul, Pow, Sum, Sym, assocLaguerre, assocLegendre, chebyshevt, chebyshevtRoot, chebyshevu, chebyshevuRoot, diff, dummyEq, exp, expand, fn, gegenbauer, hermite, hermiteProb, isUnsolved, jacobi, jacobiNormalized, laguerre, legendre, mathieuc, mathieucprime, mathieus, mathieusprime, oo, rational, rewrite, symbols, unchanged } from '../src';
